{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The COVID-19 pandemic has caused morbidity and mortality, as well as, widespread disruption to people's lives and livelihoods around the world. Given the health and economic threats posed by the pandemic to the global community, there are concerns that rates of suicide and suicidal behaviour may rise during and in its aftermath.",
      "reason": "The abstract describes the context of the COVID-19 pandemic and the uncertainty regarding its impact on suicide rates."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Our LSR will provide a regular synthesis of the most up-to-date research evidence to guide public health and clinical policy to mitigate the impact of COVID-19 on suicide.",
      "reason": "The abstract explains the need for the review to provide up-to-date evidence to guide policy and mitigate the impact of the pandemic on suicide."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not indicate the existence of other similar systematic reviews that require differentiation."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of a specific intervention effect; it is a broad review of the impact of the COVID-19 pandemic on suicidal behavior."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The overarching aim of the review is to identify and appraise any newly published evidence from around the world that assesses the impact of the COVID-19 pandemic on suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, or that assesses the effectiveness of strategies to reduce the risk of suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, resulting from the COVID-19 pandemic.",
      "reason": "The review explicitly states its overarching aim and specific research questions in the text, covering both the impact of the pandemic and the effectiveness of strategies."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies must address one of the following research questions: (i) What is the prevalence/incidence? ... (ii) What is the comparative prevalence/incidence? ... Impact of infection with COVID-19 (self or family member) on each outcome ... Prevalence/incidence of each outcome during pandemic vs not during pandemic",
      "reason": "The review includes the assessment of intervention effects (strategies to reduce risk) and comparative prevalence, and the planned comparisons are clearly defined within the eligibility criteria section."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Study participants may be adults or children of any ethnicities living in any country. Outcomes of interest are: Deaths by suicide; Self-harm (intentional self-injury or self-poisoning regardless of motivation and intent) or attempted suicide (including hospital attendance and/or admission for these reasons); Suicidal thoughts/ideation... Studies must address one of the following research questions: (i) What is the prevalence/incidence? ... (ii) What is the comparative prevalence/incidence?",
      "reason": "The manuscript specifies the study population (adults/children), outcomes of interest (suicide, self-harm, suicidal thoughts), and the research questions (prevalence/incidence, comparative prevalence/incidence) used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "No restrictions were placed on the types of study design eligible for inclusion, except for the exclusion of single-person case reports. Pre-prints were re-assessed at the time of publication and most current version included. There was no restriction on language of publication.",
      "reason": "The manuscript specifies eligibility criteria regarding study design (no restrictions except single-person case reports), publication status (pre-prints included), and language (no restrictions)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; this distinction is not applicable to the reported methodology."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "We synthesised studies according to themes based on research questions and study design, using tables and narrative. Results were synthesised separately for studies in the general population, in health and social care staff and other at-risk occupations, and in vulnerable populations",
      "reason": "The manuscript specifies how studies were grouped for synthesis (by themes based on research questions, study design, and population groups: general population, health/social care staff, and vulnerable populations)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "We did not include Google Trends studies (Jacobson et al ., 2020; Knipe et al ., 2020; Rana, 2020; Sinyor et al ., 2020) since search data constitute a proxy measure but findings are largely mixed. We also excluded grey literature (Fancourt & Steptoe, 2020).",
      "reason": "The manuscript provides a rationale for the exclusion of specific types of studies (Google Trends studies and specific grey literature)."
    }
  ],
  "confidence": 100
}

